#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 1e5 + 5;
const int E = N << 1;
const int mod = 998244353;

int n, m;
int h[N], to[E], nx[E], et;
int d[N];
int ans;

void ae(int u, int v) {
    to[++et] = v;
    nx[et] = h[u];
    h[u] = et;
}

void dfs(int u, int p=0) {
    d[u] = d[p] + 1;
    for (int i = h[u]; i; i = nx[i]) {
        int v = to[i];
        if (v == p)
            continue;
        if (!d[v])
            dfs(v, u);
        if (d[v] < d[u])
            ans = 1ll * ans * (d[u] - d[v] + 1) % mod;
    }
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i++) {
        int u, v;
        scanf("%d%d", &u, &v);
        ae(u, v);
        ae(v, u);
    }
    ans = 1;
    dfs(1);
    printf("%d\n", ans);
    return 0;
}

#include <cstdio>
#include <algorithm>
#include <queue>
using namespace std;

const int N = 505;
const int E = 1005;
const int oo = 1e9;

int n, m;
int h[N], to[E], nx[E], l[E], t[E];
int d[N][N];
priority_queue<pair<int, int> > q;

void calc(int u, int d[]) {
    for (int i = 1; i <= n; i++)
        d[i] = -oo;
    d[u] = oo;
    q.push(make_pair(d[u], u));
    while (!q.empty()) {
        pair<int, int> p = q.top();
        q.pop();
        if (d[p.second] != p.first)
            continue;
        int u = p.second;
        for (int i = h[u]; i; i = nx[i]) {
            int v = to[i];
            int w = min(d[u] - t[i], l[i]);
            if (w < 0)
                continue;
            if (w > d[v]) {
                d[v] = w;
                q.push(make_pair(d[v], v));
            }
        }
    }
}

int main() {
    int q;
    scanf("%d%d%d", &n, &m, &q);
    for (int i = 1; i <= m; i++) {
        int u, v;
        scanf("%d%d%d%d", &u, &v, &l[i], &t[i]);
        to[i] = u;
        nx[i] = h[v];
        h[v] = i;
    }
    for (int i = 1; i <= n; i++)
        calc(i, d[i]);
    while (q--) {
        int u, v, s;
        scanf("%d%d%d", &u, &v, &s);
        if (s <= d[v][u])
            printf("Yes\n");
        else
            printf("No\n");
    }
    return 0;
}
